public class CollectionDecisionMatrixExample {
    // High-frequency random reads, occasional appends: Use ArrayList with pre-allocated capacity
    private final List<Transaction> auditLog = new ArrayList<>(10_000);

    // Fast O(1) lookups and uniqueness enforcement: Use HashSet
    private final Set<String> activeSessionIds = new HashSet<>();

    // Multi-threaded concurrent reads with infrequent writes: Use ConcurrentHashMap
    private final Map<String, UserSession> sessionCache = new ConcurrentHashMap<>();

    public void recordTransaction(Transaction tx) {
        auditLog.add(tx); // O(1) amortized
        activeSessionIds.add(tx.getSessionId());
    }
}
